def bubbleSortWithStats(array):
  comparisons = 0
  swaps = 0
  n = len(array)
  for i in range(n - 1):
    for j in range(n - i - 1):
      comparisons += 1
      if array[j] > array[j + 1]:
        array[j], array[j + 1] = array[j + 1], array[j]
        swaps += 1
  return {"sortedArray": array, "comparisons": comparisons, "swaps": swaps}

def selectionSortWithStats(array):
  comparisons = 0
  swaps = 0
  n = len(array)
  for i in range(n - 1):
    minIdx = i
    for j in range(i + 1, n):
      comparisons += 1
      if array[j] < array[minIdx]:
        minIdx = j
    if minIdx != i:
      array[i], array[minIdx] = array[minIdx], array[i]
      swaps += 1
  return {"sortedArray": array, "comparisons": comparisons, "swaps": swaps}

